mapper.update:
update account_deregistration
set status = 'CANCELLED', cancel_time = #{cancelTime}, update_time = #{cancelTime}
where member_id = #{memberId} and status = 'PENDING'

update ums_member
set deregister_status = 'PENDING', deregister_apply_time = #{applyTime}, deregister_execute_after = #{executeAfter}, update_time = #{applyTime}
where id = #{memberId} and del_flag = 0

update cms_registration
set real_name = '已注销用户', phone = null, phone_hash = null, email = null, address = null, address_id = null, update_time = now()
where member_id = #{memberId}

update account_deregistration
set status = 'FAILED', failure_reason = #{reason}, update_time = #{time}
where id = #{id} and status = 'PENDING'

update account_deregistration
set status = 'COMPLETED', complete_time = #{completeTime}, update_time = #{completeTime}
where id = #{id} and status = 'PENDING'
